INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (8, 10, 'theory', 'Quiz: VFS, the page cache and disks');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 10, 0, 'When does write() return control?', '["Only after the data is written to disk", "Only after the device confirms it", "After the data is copied into the page cache, before it reaches the disk", "Only after the next fsync"]', 2, 'Pages are marked dirty, and the writeback threads flush them later. So a fast write does not mean "data on disk".');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 10, 1, 'How can a program guarantee that data has reached the device?', '["Call fsync and wait for it to finish", "Call write twice", "Close the file with close", "Turn off the page cache with the free command"]', 0, 'The file system journal protects metadata, while the file contents are protected only by fsync.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 10, 2, 'What does a dentry store in the VFS?', '["The file data", "The mount table", "User permissions", "The link between a name and an inode; such entries are cached and speed up path lookup"]', 3, 'Together with the superblock, the inode and the open file, these are the four VFS objects.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 10, 3, 'Which I/O scheduler is usually chosen for fast NVMe drives?', '["bfq", "none: sorting only gets in the way on fast devices", "mq-deadline, always", "No scheduler is needed: there is no block layer"]', 1, 'mq-deadline and kyber suit disks and special workloads, bfq suits workstations.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 10, 4, 'What does the 3-2-1 backup rule say?', '["Three copies on two different media, one of them offsite", "Three disks in RAID, two mirrors, one spare", "A copy every three hours, on two servers, kept for a year", "Three disks in RAID, two controllers, one power supply"]', 0, 'RAID survives a disk failure, but not a deleted file or ransomware, so it does not replace a backup.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 10, 5, 'Why call fsync after write if data safety matters?', '["write writes nothing until you close the file", "fsync compresses the file on disk", "write only puts the data into the page cache, and fsync makes the kernel write it to the device", "fsync is only needed for directories"]', 2, 'A successful write does not guarantee the data would survive a power failure. Durability comes from fsync (or the O_SYNC flags).');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 10, 6, 'What does the virtual file system use operation tables for?', '["It is a list of files in a directory", "It is a set of function pointers of a particular file system: the layer calls them without knowing what is underneath", "It is a log of changes on disk", "It is a cache of access rights"]', 1, 'That is how a read call works the same way with ext4, XFS, tmpfs and /proc: each file system has its own table of functions.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (8, 10, 7, 'Which I/O scheduler is usually chosen for a fast NVMe drive with several hardware queues?', '["bfq: it is always faster", "Any except none", "None: a scheduler cannot be turned off", "none: reordering requests here only adds latency"]', 3, 'A scheduler is needed to smooth out slow mechanics. On fast SSDs the device itself serves the queues.');
